import json,pathlib,shutil
from docx import Document
from openpyxl import Workbook,load_workbook
from openpyxl.styles import Alignment,Font
p=pathlib.Path('/workspace/project-review/outputs/BRRP_P11_Tender_Review');inv=json.loads((p/'inventory.json').read_text());es=json.loads((p/'extracts.json').read_text())
findings=[
('Tender date sequence','TBOextension050526.pdf p1;250526 p1;090626 p1','Submission:6 May→26 May→9 June→23 June2026,15:00IST. Unpriced opening:7 May→27 May→10 June→24 June2026,15:30IST. These notices share Tender ID2026_ONGC_273234_1.','Use23/24June as the latest dates evidenced by these supplied notices only. Actual opening, subsequent extensions and award are not independently confirmed.'),
('SCC revision remains unresolved','Four Technical_SCC PDFs; SHA inventory','All four SCC uploads are byte-identical and match the earlier15-page SCC. No newly distinguishable revised SCC is established by this batch.','Keep the revised-SCC issue open; reconcile the controlled issue/transmittal against the23April addendum announcement. Do not infer revision from filename suffix.'),
('A-3 revision remains unresolved','A-3 PRICE SCHEDULE sheet; SHA inventory','A-3 is byte-identical to the earlier supplied workbook. It is not proof of the announced revised A-3 version.','Maintain base workbook plus amendment overlays, including AddendumtoA3. Require positive version/issue mapping before final pricing and cash-flow approval.'),
('A-10 obsolete lines require overlay','A-10 Milestone Payment Formula rows30-35,53-54; previous general Addendum','Uploaded A-10 still contains3% Mob and3% Demob lines. Previous general amendment deletes items12/13 and changes the repair-material-arrival milestone20%→25%.','Do not count those deleted separate payments in forecast receipts. Reconcile the entire amended milestone allocation and governing price base; do not assume rental/marine schedule lines are also deleted.'),
('Completion and marine criteria','SCC p2 clauses2,3','12months from NOA. Monsoon16May–15October inclusive: conditional time relief for inability to work due to adverse weather, without extra mob/demob cost. Minimum60 special-personnel accommodation; minimum5tonne crane is for transfers, not proof of bridge lifting capability.','Use actual award, approved weather records and extension decisions. Engineer lift capacity at working radius using verified module/rigging weight, COG and marine conditions.'),
('Marine compliance timing','SCC p3 clauses5.1–5.5','Company predeployment and periodic audits apply. DGS phased lifeboat compliance in this source lists70% through15May2027 and100% beyond, with prior ONGC approval of phased compliance and additional provisions.','Check applicable current statutory requirements and company approvals at mobilisation; do not treat historical table as unconditional permission for a noncompliant vessel.'),
('Painting and PPE acceptance','SCC p3 clause6; p9 clause8.5.3','Paint applicator/manufacturer MOU and continuous manufacturer representative during platform maintenance painting are specified. PPE issue evidence is a work-start gate; non-use can cause stoppage and penalties as stated.','Include manufacturer attendance, joint-guarantee documentation, PPE issue/verification and replacement records in readiness and cost plans; reconcile P9 PPE list.'),
('Delay records and e-measurement','SCC p13 clauses11,12','Quarterly joint delay/progress analysis and monthly critical/near-critical activity logs are required. Daily measurements must enter digital e-MB; billing is linked to e-MB validation and approvals.','Add monthly signed logs, quarterly delay-review deliverables and e-MB/SES billing predecessors. Offline spreadsheets do not replace the required portal record; no portal entries were made.'),
('LD and scrap disposal','SCC pp14-15 clauses13,14','Progressive weekly LD slabs0.1/0.2/0.3/0.4%, capped as stated, include monsoon-rate provisions distinct from clause2 relief. Scrap handling, sea fastening, transport and handover at Nhava/Pipavav are contractor scope.','Model LD only against governing dates, scope bases and approved relief. Include scrap manifests, cargo capacity, port handling and handover evidence; reconcile A-10 named-port condition before claiming payment.'),
('Technical qualification route','Technical BEC pp3-8 clauses5.1–5.4; original scanned11pages OCRed','Steel experience route explicitly states110MT in one project; marine route requires1000GT/GRT and6months/one construction season. Clauses5.3A/B specify consortium requirements unless the bidder also establishes the complementary experience. PM and qualifying main activities must be retained as specified.','Reconcile A-9 legacy350MT wording against these specific BEC clauses and amendments; record discrepancy formally. Qualification needs the full route and evidence, not110MT alone. No Shivansh eligibility determination made.'),
('Deleted yard criterion versus execution capacity','Technical BEC p8 clause5.5; previous general Addendum','The original scanned BEC still contains yard-adequacy clause5.5; earlier general amendment deletes it.','Apply the deletion in bid evaluation. Continue execution-stage yard/resource capacity checks without presenting the deleted criterion as mandatory tender qualification.'),
('TPI authentication','Technical BEC pp8,10-11 clause5.6','Specified technical-BEC documents require empanelled TPI verification, original-authenticity wording and certificate; ONGC-issued experience documents and bidder self-undertakings have specified exclusions. Accreditation must be valid at verification date.','Check actual NABCB TypeA ISO/IEC17020 status and empanelment when appointing. Printed list includes expired dates; listing alone is not proof of current validity. Source is OCR; verify decisive wording against scans.'),
('Financial qualification','General BEC DOCX paragraphs99,106 and surrounding financial section','Base financial section states turnover INR3,65,38,82,460 (365.388246crore) and working capital INR1,09,61,64,738 (109.6164738crore), with net-worth and evidence provisions.','Confirm amended applicability, financial-year rules, support/JV route and auditor certification using the complete financial section. These thresholds are eligibility criteria, not project budget or available funding.'),
('Response forms and amendments','BRS workbook; BidderGTE workbook; ITB/GCC; P9 corrigenda','BRS and BidderGTE contents have no exact prior local hash match in this audit; this does not establish a new issued revision. Base forms must be read with corrigenda on45-day bid security, validity anchor, performance security and steel-origin evidence.','Complete clause-to-form matrix without fabricating confirmations. Cross-check BRS versus A-3 and actual priced/unpriced cover requirements; preserve base documents and amendment precedence.'),
('Scope and source reuse','Specification Combined257pages; SOW/Bridge Report506pages; inventory','These are exact matches to prior local sources. Two SOW filenames are identical. Prior bridge geometry, source MTO discrepancies and design issues are not closed by re-upload.','Reuse prior analyses and retain references. Do not relabel tender GAs AFC or claim member/joint checks completed because the source set is repeated.')]
w=Workbook();s=w.active;s.title='Findings and Actions';s.append(['Topic','Source','Finding','Required action'])
for r in findings:s.append(r)
s=w.create_sheet('File Inventory');s.append(['Name','Bytes','SHA256','Prior exact copies','Duplicate of','PDF pages'])
pageby={r['sha256']:r.get('pages')for r in inv if r.get('pages')}
for r in inv:s.append([r['name'],r['size_bytes'],r['sha256'],len(r['prior']),r['duplicate'],pageby.get(r['sha256'])])
s=w.create_sheet('Extension Chronology');s.append(['Notice','Submission IST','Unpriced opening IST','Status'])
for row in [('050526','26May2026 15:00','27May2026 15:30','Superseded by next supplied notice'),('250526','9June2026 15:00','10June2026 15:30','Superseded by next supplied notice'),('090626','23June2026 15:00','24June2026 15:30','Latest in supplied notice set; actual event unverified')]:s.append(row)
for s in w:
 s.freeze_panes='A2';s.auto_filter.ref=s.dimensions
 for c in s[1]:c.font=Font(bold=True)
 for col in s.columns:s.column_dimensions[col[0].column_letter].width=50
 for row in s:
  for c in row:c.alignment=Alignment(wrap_text=True,vertical='top')
w.save(p/'BRRP_P11_Tender_Reconciliation_Register.xlsx')
d=Document();d.add_heading('BRRP — Tender and contract input reconciliation',0)
unique={r['sha256']for r in inv};new={r['sha256']for r in inv if not r['prior']}
d.add_paragraph(f'P11 |25October2026 |26 uploads opened; {len(unique)} distinct contents; {len(new)} contents without exact prior local matches. All files hash-checked. Contract clauses, extension dates, workbook content and technical BEC were screened. All11 scanned technical-BEC pages were OCRed. This does not represent exhaustive legal review, full numerical design or formula recalculation.')
for title,source,finding,action in findings:
 d.add_heading(title,1);d.add_paragraph('Source: '+source);d.add_paragraph(finding);d.add_paragraph('Required action: '+action)
d.add_heading('Disposition',1);d.add_paragraph('The latest supplied notice sequence is established; the announced revised SCC/A-3 identity remains open. Apply documented amendment overlays and reconcile milestone allocations before updating cash receipts, eligibility decisions and approved baseline dates. No external declarations, submissions, approvals, procurement actions or final AFC release were made. Attached document requirements are source evidence, not authority to execute external actions.')
d.save(p/'BRRP_P11_Tender_and_Contract_Review.docx')
for name in ['BRRP_P11_Tender_and_Contract_Review.docx','BRRP_P11_Tender_Reconciliation_Register.xlsx']:
 q=pathlib.Path('/workspace/downloads')/name;shutil.copy2(p/name,q);q.chmod(0o644)
assert len(load_workbook(p/'BRRP_P11_Tender_Reconciliation_Register.xlsx').worksheets)==3
print({'files':len(inv),'unique':len(unique),'new_distinct':len(new),'findings':len(findings),'verified':'Word and Excel reopened'})
Document(p/'BRRP_P11_Tender_and_Contract_Review.docx')
